<script setup lang="ts">import{reactive,ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{Plus}from'lucide-vue-next';const rows=ref<any[]>([]),open=ref(false),error=ref(''),secret=ref('');const form=reactive({name:'ERP principal',url:'https://erp.exemplo.com/webhooks/hubfiscal',events:['document.created','job.completed']});const cols=[{key:'name',label:'Webhook'},{key:'url',label:'URL'},{key:'events',label:'Eventos'},{key:'active',label:'Situação'}];async function load(){rows.value=(await api.get('/webhooks')).data}async function save(){try{const{data}=await api.post('/webhooks',form);secret.value=data.secret;open.value=false;await load()}catch(e){error.value=errorMessage(e)}}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))
</script><template><PageHeader title="Webhooks" subtitle="Entregue eventos fiscais aos ERPs com assinatura e rastreamento"><button class="btn primary" @click="open=true"><Plus :size="16"/>Novo webhook</button></PageHeader><div v-if="secret" class="secret-box"><strong>Segredo HMAC gerado</strong><code>{{secret}}</code></div><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-events="{value}"><div class="tag-list"><span v-for="e in value">{{e}}</span></div></template><template #cell-active="{value}"><StatusBadge :status="value?'active':'disabled'"/></template></DataTable></section><Modal :open="open" title="Novo webhook" @close="open=false"><form class="form-grid" @submit.prevent="save"><label>Nome<input v-model="form.name" required/></label><label>URL<input v-model="form.url" type="url" required/></label><label class="span-2">Eventos<input value="document.created, job.completed" disabled/></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button class="btn primary">Salvar</button></div></form></Modal></template>
